//! The generator story's driver (plan §3.2's row for `aeolus-data`:
//! "Generated by `xtask` into committed Rust (phf/trie). Also
//! generates: docs …") — the thin CLI over [`aeolus_data::codegen`]'s
//! artifact seam, in the shape the workspace's other driver already
//! established (the aeolus-cli precedent: the whole program is the
//! library `run(args, out, err) -> code`, argument list WITHOUT the
//! argv-0 program name, two sinks, exit code back).
//!
//! ```text
//! cargo xtask list                     — the committed artifact list
//! cargo xtask gen-tables               — (re)write every artifact's
//!                                        committed bytes from the rows
//! cargo xtask verify-tables            — the drift gate: regenerate and
//!                                        compare, exit 1 on ANY drift
//! cargo xtask gen-tables --check       — verify-tables' alias
//!                                        (the CI-friendly spelling)
//! cargo xtask gen-gpui-caps            — (re)write the §3.7 capability
//!                                        table (the codegen-gpui src
//!                                        module)
//! cargo xtask verify-gpui-caps         — the capability table's
//!                                        focused drift gate
//! ```
//!
//! Both commands take `--root <dir>` to resolve the artifacts'
//! workspace-relative paths against somewhere other than this
//! workspace (the driver tests run write mode against a temp root, so
//! a test never mutates the real tree).
//!
//! The drift discipline this enforces is the plan §8 story ("`cargo
//! xtask gen-tables` … so API drift is detectable"): the committed
//! bytes are the rows' regeneration, pinned equal in
//! `aeolus-data/tests/codegen.rs` (which runs in `cargo test` without
//! this driver) AND verifiable here in one command before a commit.

use std::path::{Path, PathBuf};

use aeolus_codegen::conformance::{Capability, Conformance, PropCapability, TableCaps, Tier};
use aeolus_codegen_gpui::{Caps, unsupported_reason};
use aeolus_data::codegen::{self, GeneratedArtifact};
use aeolus_ir::Prop;

/// The driver's usage text (the `--help` surface and the usage-error
/// suffix; the same single-source shape as the CLI's `USAGE`).
const USAGE: &str = "aeolus xtask — the committed-artifact generator\n\n\
USAGE:\n    \
cargo xtask list\n    \
cargo xtask gen-tables [--check] [--root <dir>]\n    \
cargo xtask verify-tables [--root <dir>]\n    \
cargo xtask gen-gpui-caps [--check] [--root <dir>]\n    \
cargo xtask verify-gpui-caps [--root <dir>]\n\n\
commands:\n    \
list             print every committed artifact (name + workspace path)\n    \
gen-tables       regenerate every artifact's committed bytes from the rows\n    \
verify-tables    regenerate and compare; exit 1 on any drift (the test battery pins it)\n    \
gen-gpui-caps    regenerate the §3.7 capability table (the codegen-gpui src module)\n    \
verify-gpui-caps the capability table's focused drift gate (exit 1 on drift)\n\n\
flags:\n    \
--check        gen commands: compare instead of write (the verify behaviour)\n    \
--root <dir>   resolve the artifacts' workspace-relative paths against <dir>\n    \
               (default: this workspace's root)\n";

/// Exit codes: `0` clean / written, `1` drift (verify mode), `2` usage
/// error — the CLI's own code contract.
const EXIT_OK: i32 = 0;
const EXIT_DRIFT: i32 = 1;
const EXIT_USAGE: i32 = 2;

/// The default workspace root: this crate lives at `crates/xtask`, so
/// the workspace root is two directories up (compile-time constant —
/// the driver behaves the same from any working directory).
fn default_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..")
}

/// One command outcome the driver reports per artifact — the shared
/// shape of the write and verify reports.
enum Outcome {
    /// Verify mode: the committed bytes equal the regeneration.
    Clean,
    /// Verify mode: the committed bytes differ (the gate's exit-1 case).
    Drifted,
    /// Verify mode: the file the artifact commits to is missing.
    Missing,
    /// Write mode: the regeneration replaced the committed bytes.
    Wrote(usize),
}

impl Outcome {
    /// The one-line report (the driver's whole output surface).
    fn report(&self, name: &str, path: &str) -> String {
        match self {
            Self::Clean => format!("{name}  {path}  clean\n"),
            Self::Drifted => format!("{name}  {path}  DRIFTED — run `cargo xtask gen-tables`\n"),
            Self::Missing => format!("{name}  {path}  MISSING — run `cargo xtask gen-tables`\n"),
            Self::Wrote(bytes) => format!("{name}  {path}  wrote {bytes} bytes\n"),
        }
    }
}

// ---------------------------------------------------------------------------
// The corpus-at-scale score (the M1 scale-up's second conformance line)
// ---------------------------------------------------------------------------

/// The committed golden corpus (`crates/aeolus-core/tests/fixtures/
/// golden.corpus`, the M1 scale-up's 2992-entry regeneration through the
/// real tailwindcss v4.1.17) — the corpus-at-scale score's subject.
const GOLDEN_CORPUS: &str =
    include_str!("../../../crates/aeolus-core/tests/fixtures/golden.corpus");

/// The per-entry verdict one backend's corpus-at-scale score rides: the
/// entry compiles through the V1 pipeline under its own theme's baked
/// table (zero diagnostics) AND every lowered longhand lands
/// native/polyfill on the backend's capability table. A compile refusal
/// (the documented typed-refusal surface) or a refused longhand makes
/// the entry not expressible — honest either way.
struct CorpusScale {
    entries: usize,
    expressible: usize,
}

/// Walk the corpus against one capability. Deterministic: the corpus
/// bytes are committed, the token tables bake from committed CSS, the
/// compile walk is the same one the batteries pin.
fn corpus_scale(capability: &impl Capability) -> CorpusScale {
    use aeolus_compile::{Config, compile_theme};
    use aeolus_theme::{ThemeSource, TokenTable};

    let default_source =
        ThemeSource::from_css(aeolus_core::TAILWIND_DEFAULT_THEME, None).expect("default parses");
    let default = TokenTable::baked(&default_source).expect("default bakes");
    let shadcn_source = ThemeSource::shadcn().expect("shadcn parses");
    let shadcn = TokenTable::baked(&shadcn_source).expect("shadcn bakes");
    let config = Config::default();

    let mut scale = CorpusScale {
        entries: 0,
        expressible: 0,
    };
    let mut theme = String::new();
    for line in GOLDEN_CORPUS.lines() {
        if let Some(rest) = line.strip_prefix("@theme ") {
            theme = rest.trim().to_string();
            continue;
        }
        let Some(rest) = line.strip_prefix("@entry ") else {
            continue;
        };
        let (_entry_theme, class) = rest.split_once(' ').expect("entry line shape");
        scale.entries += 1;
        let table = if theme == "shadcn" { &shadcn } else { &default };
        let expressible = match compile_theme(class, table, &config) {
            Ok(compiled) => {
                compiled.diagnostics.is_empty()
                    && compiled.program.layers.iter().all(|layer| {
                        layer
                            .decls
                            .iter()
                            .all(|decl| capability.tier(decl.prop) != Tier::Refused)
                    })
            }
            Err(_) => false,
        };
        if expressible {
            scale.expressible += 1;
        }
    }
    scale
}

/// The corpus-at-scale line the six conformance pages render under the
/// per-longhand ceiling table: the EXPANDED corpus's entry-level
/// expressibility for the backend (the §5.1 "at scale" measure). The
/// ceiling score above stays the per-longhand share over the
/// longhand list — the two numbers answer different questions (can the
/// backend carry a longhand at all; can it carry a real class fully).
fn corpus_scale_section(capability: &impl Capability) -> String {
    let scale = corpus_scale(capability);
    let pct = scale.expressible as f32 / scale.entries.max(1) as f32 * 100.0;
    format!(
        "\n**corpus at scale: {} entries — {:.2}% expressible** (per-entry share of the \
         expanded golden.corpus; an entry counts when every lowered longhand lands \
         native/polyfill. The ceiling score above is the per-longhand share over the \
         {} longhands — the two answer different questions.)\n",
        scale.entries,
        pct,
        Prop::ALL.len(),
    )
}

// ---------------------------------------------------------------------------
// The conformance page: the §5.1 score's committed artifact
// ---------------------------------------------------------------------------

/// The committed per-backend conformance page (`docs/CONFORMANCE.md`,
/// plan §5.1's "publish a per-backend conformance score") — the
/// [Conformance] report rendered from the backends' OWN capability
/// impls (`Caps`, the emit gates' own tables), so the page is the
/// emitter's verdicts, never a parallel claim. The driver extends the
/// data crate's artifact list with it (the trait lives there; the
/// render inputs live above it in the dependency graph), and the same
/// gen/verify walk pins the page's drift from then on.
struct ConformanceDocs;

impl GeneratedArtifact for ConformanceDocs {
    fn name(&self) -> &'static str {
        "conformance-docs"
    }

    fn path(&self) -> &'static str {
        "docs/CONFORMANCE.md"
    }

    fn generate(&self) -> String {
        let mut out = String::with_capacity(4096);
        out.push_str(
            "<!-- GENERATED by `cargo xtask gen-tables` from the \
`aeolus_codegen::conformance::Capability` impls (the emit gates' own capability \
tables) — DO NOT EDIT. The committed bytes are pinned by `cargo xtask \
verify-tables`; a capability edit that forgets the regeneration fails the \
gate. -->\n\n",
        );
        // The registered backends' reports, one section each. The list
        // grows with the workspace's capability impls (GPUI today — the
        // plan §3.7 matrix's first backend; the five plan-path backends
        // report through the plan bridge's typed notes instead).
        let report = Conformance::of(&Caps);
        out.push_str(&report.to_string());
        // The M1 scale-up's second line: the expanded corpus's
        // entry-level expressibility for this backend.
        out.push_str(&corpus_scale_section(&Caps));
        out
    }
}

// ---------------------------------------------------------------------------
// The five interpreter backends' capability tables: the conformance
// moat's committed rows
// ---------------------------------------------------------------------------

/// One interpreter backend's verdict replay, as the generator sees it:
/// the backend's own `caps::walk_capabilities()` rows + the static
/// table name the freeze lands in.
struct BackendReplay {
    name: &'static str,
    doc: &'static str,
    table: &'static str,
    rows: fn() -> Vec<(Prop, bool, bool, String)>,
}

/// The committed five-backend table
/// (`crates/aeolus-codegen/src/caps_tables.rs`, the conformance moat's
/// framework-free rows — the `caps_generated.rs` pattern at the
/// interpreter lanes): each backend's own `walk_capabilities()`
/// replay, frozen into the committed module the drift pins beside the
/// backends assert equal. The CLI's `--target` face and the per-backend
/// docs pages render THROUGH these rows — the published scores are the
/// emitters' verdicts, never a parallel claim.
struct BackendCaps;

impl GeneratedArtifact for BackendCaps {
    fn name(&self) -> &'static str {
        "backend-caps"
    }

    fn path(&self) -> &'static str {
        "crates/aeolus-codegen/src/caps_tables.rs"
    }

    fn generate(&self) -> String {
        let replays: &[BackendReplay] = &[
            BackendReplay {
                name: "xilem",
                doc: "the masonry property-stack lane's committed verdicts",
                table: "XILEM_CAPABILITIES",
                rows: aeolus_xilem::caps::walk_capability_flags,
            },
            BackendReplay {
                name: "floem",
                doc: "the own-walk reactive lane's committed verdicts",
                table: "FLOEM_CAPABILITIES",
                rows: aeolus_floem::caps::walk_capability_flags,
            },
            BackendReplay {
                name: "iced",
                doc: "the native-style lane's committed verdicts",
                table: "ICED_CAPABILITIES",
                rows: aeolus_iced::caps::walk_capability_flags,
            },
            BackendReplay {
                name: "egui",
                doc: "the painted-surface lane's committed verdicts",
                table: "EGUI_CAPABILITIES",
                rows: aeolus_egui::caps::walk_capability_flags,
            },
            BackendReplay {
                name: "slint",
                doc: "the property-tree lane's committed verdicts",
                table: "SLINT_CAPABILITIES",
                rows: aeolus_slint::caps::walk_capability_flags,
            },
        ];
        let mut body = String::with_capacity(16_384);
        for replay in replays {
            body.push_str(&format!(
                "/// {} — {} (the drift pin beside the backend re-runs the replay).\n#[rustfmt::skip]\npub static {}: &[PropCapability] = &[\n",
                replay.name, replay.doc, replay.table
            ));
            for (prop, landed, polyfill, reason) in (replay.rows)() {
                let tier = match (landed, polyfill) {
                    (true, false) => "Native",
                    (true, true) => "Polyfill",
                    (false, _) => "Refused",
                };
                // The reason rides ONLY the refused rows (the
                // PropCapability contract: an expressible longhand
                // carries the empty reason — the best-tier replay's
                // recorded refusal text is the demotion audit trail,
                // not the published row).
                let reason = match tier {
                    "Refused" => reason,
                    _ => String::new(),
                };
                let reason = reason.replace('\\', "\\\\").replace('"', "\\\"");
                body.push_str(&format!(
                    "    PropCapability {{ prop: Prop::{prop:?}, tier: Tier::{tier}, reason: \"{reason}\" }},\n"
                ));
            }
            // The last table ends the file WITHOUT the blank line (the
            // rustfmt-stable bytes the verify gate pins).
            if replay.table != "SLINT_CAPABILITIES" {
                body.push_str("];\n\n");
            } else {
                body.push_str("];\n");
            }
        }
        format!(
            "//! The five interpreter backends' committed capability tables (plan\n\
             //! §5.1's conformance moat: six published scores, no parallel claims).\n\
             //!\n\
             //! GENERATED by `cargo xtask gen-tables` from each backend's own\n\
             //! `caps::walk_capabilities()` replay (the registry-driven probe\n\
             //! corpus through the backend's REAL `lower_program` lane) — DO NOT\n\
             //! EDIT. The committed bytes are pinned equal to a fresh replay by the\n\
             //! drift test beside each backend (`crates/aeolus-<backend>/tests/\n\
             //! caps_table.rs`), and `cargo xtask verify-tables` gates the same\n\
             //! equality from the CLI side; a walk-verdict edit that forgets the\n\
             //! regeneration fails `cargo test` first.\n\
             //!\n\
             //! The rows' semantics: one [`PropCapability`] per IR longhand in\n\
             //! `Prop::ALL`'s own (cascade) order — the tier the backend's walk\n\
             //! answers and, for a refused longhand, the report's own boundary\n\
             //! text. An expressible longhand carries the empty reason. The\n\
             //! framework-free tables are the `aeolus audit --target <backend>`\n\
             //! face's verdict source and the `docs/CONFORMANCE-<backend>.md`\n\
             //! pages' renderer ([`crate::conformance::TableCaps`]).\n\n\
             use crate::conformance::PropCapability;\n\
             use crate::conformance::Tier;\n\
             use aeolus_ir::Prop;\n\n\
             {body}"
        )
    }
}

// ---------------------------------------------------------------------------
// The per-backend conformance pages: the six published scores
// ---------------------------------------------------------------------------

/// One committed per-backend conformance page
/// (`docs/CONFORMANCE-<backend>.md`, the moat's publish face for the
/// five interpreter lanes — the GPUI page
/// ([`ConformanceDocs`], `docs/CONFORMANCE.md`) the §5.1 seam already
/// renders): the [Conformance] report from the committed
/// [`TableCaps`] rows, which are the backend's own walk freezes (the
/// drift pins beside the backends keep them equal to a fresh replay).
struct ConformanceBackendDocs {
    name: &'static str,
    table: &'static [PropCapability],
}

impl GeneratedArtifact for ConformanceBackendDocs {
    fn name(&self) -> &'static str {
        match self.name {
            "xilem" => "conformance-xilem",
            "floem" => "conformance-floem",
            "iced" => "conformance-iced",
            "egui" => "conformance-egui",
            _ => "conformance-slint",
        }
    }

    fn path(&self) -> &'static str {
        match self.name {
            "xilem" => "docs/CONFORMANCE-xilem.md",
            "floem" => "docs/CONFORMANCE-floem.md",
            "iced" => "docs/CONFORMANCE-iced.md",
            "egui" => "docs/CONFORMANCE-egui.md",
            _ => "docs/CONFORMANCE-slint.md",
        }
    }

    fn generate(&self) -> String {
        let caps = TableCaps::new(self.name, self.table);
        let mut out = String::with_capacity(4096);
        out.push_str(
            "<!-- GENERATED by `cargo xtask gen-tables` from the committed \
`caps_tables` rows (the backend's own `walk_capabilities()` freeze, the drift \
pins beside the backend keep them equal to a fresh replay) — DO NOT EDIT. The \
committed bytes are pinned by `cargo xtask verify-tables`; a walk-verdict edit \
that forgets the regeneration fails the gate. -->\n\n",
        );
        out.push_str(&Conformance::of(&caps).to_string());
        // The M1 scale-up's second line: the expanded corpus's
        // entry-level expressibility for this interpreter lane.
        out.push_str(&corpus_scale_section(&caps));
        out
    }
}

// ---------------------------------------------------------------------------
// The GPUI capability table: the §3.7 generator slice's committed module
// ---------------------------------------------------------------------------

/// The committed per-longhand capability table
/// (`crates/aeolus-codegen-gpui/src/caps_generated.rs`, the §3.7
/// matrix's generated form — the slice the architecture doc sketched
/// and this driver now lands): the [Conformance] partition's
/// per-longhand rows rendered from the backends' OWN capability impls
/// (`Caps` — the emit gates' own tables), so the committed module is
/// the emitter's verdicts, never a parallel claim. The crate consumes
/// the module (`aeolus_codegen_gpui::PROP_CAPABILITIES`) and pins it
/// equal in `tests/caps_generated.rs`; the same gen/verify walk pins
/// the committed bytes here.
struct GpuiCaps;

impl GeneratedArtifact for GpuiCaps {
    fn name(&self) -> &'static str {
        "gpui-caps"
    }

    fn path(&self) -> &'static str {
        "crates/aeolus-codegen-gpui/src/caps_generated.rs"
    }

    fn generate(&self) -> String {
        // One row per IR longhand, in `Prop::ALL`'s own (cascade) order:
        // the tier `Caps` answers and — for a refused longhand only —
        // the typed boundary reason the emit gate's per-prop answer
        // carries (the text-dependent verdicts say so honestly: their
        // reason names the annotation the verdict is the ROW TEXT's;
        // an expressible longhand carries the empty reason).
        let mut rows = String::with_capacity(4096);
        for prop in Prop::ALL {
            let tier = Caps.tier(*prop);
            let reason = match tier {
                Tier::Refused => unsupported_reason(*prop, "").unwrap_or_default(),
                Tier::Native | Tier::Polyfill => "",
            };
            let reason = reason.replace('\\', "\\\\").replace('"', "\\\"");
            rows.push_str(&format!(
                "    PropCapability {{ prop: Prop::{prop:?}, tier: Tier::{tier:?}, reason: \"{reason}\" }},\n"
            ));
        }
        format!(
            "//! The generated GPUI capability table — the §3.7 matrix's \
per-longhand form (plan §3.7's generator slice: the committed \
`caps_generated.rs` beside the hand-maintained tier tables it pins).\n\
//!\n\
//! GENERATED by `cargo xtask gen-gpui-caps` from \
`aeolus_codegen_gpui::Caps` (the emit gates' own verdicts over \
`Prop::ALL`) — DO NOT EDIT. The committed bytes are pinned equal to \
the regeneration in `tests/caps_generated.rs`, and `cargo xtask \
verify-gpui-caps` is the same check from the CLI side; a \
capability-table edit that forgets the regeneration fails \
`cargo test` first.\n\
//!\n\
//! The rows' semantics: one [`crate::PropCapability`] per IR longhand \
in `Prop::ALL`'s own (cascade) order — the tier the emit gates run \
and, for a refused longhand, the typed boundary reason the emit \
gate's per-prop answer carries (the text-dependent verdicts — the \
gradient direction row, the shadow and filter preset gates — name \
the annotation the verdict is the ROW TEXT's; the per-declaration \
refinements stay at the gates, the per-longhand ceiling the \
conformance page renders). An expressible longhand carries the \
empty reason.\n\n\
use aeolus_codegen::conformance::Tier;\n\
use aeolus_ir::Prop;\n\n\
use crate::PropCapability;\n\n\
/// The per-longhand verdict table ([`crate::PROP_CAPABILITIES`], the \
crate's public reading of the §3.7 matrix).\n\
#[rustfmt::skip]\n\
pub static PROP_CAPABILITIES: &[PropCapability] = &[\n\
{rows}\
];\n"
        )
    }
}

/// The FULL artifact list: the data crate's registry-derived artifacts,
/// the conformance page this driver renders from the codegen crates'
/// capability impls, and the capability table the same impls render
/// into the codegen-gpui crate's own src.
// The five interpreter lanes' committed pages (the six published
// scores — the moat's no-parallel-claims face): rendered from the SAME
// committed rows the `backend-caps` artifact freezes, so a page can
// never drift from the table it reads. Statics — the artifact list's
// `&'static dyn` shape.
static CONFORMANCE_XILEM_DOCS: ConformanceBackendDocs = ConformanceBackendDocs {
    name: "xilem",
    table: aeolus_codegen::caps_tables::XILEM_CAPABILITIES,
};
static CONFORMANCE_FLOEM_DOCS: ConformanceBackendDocs = ConformanceBackendDocs {
    name: "floem",
    table: aeolus_codegen::caps_tables::FLOEM_CAPABILITIES,
};
static CONFORMANCE_ICED_DOCS: ConformanceBackendDocs = ConformanceBackendDocs {
    name: "iced",
    table: aeolus_codegen::caps_tables::ICED_CAPABILITIES,
};
static CONFORMANCE_EGUI_DOCS: ConformanceBackendDocs = ConformanceBackendDocs {
    name: "egui",
    table: aeolus_codegen::caps_tables::EGUI_CAPABILITIES,
};
static CONFORMANCE_SLINT_DOCS: ConformanceBackendDocs = ConformanceBackendDocs {
    name: "slint",
    table: aeolus_codegen::caps_tables::SLINT_CAPABILITIES,
};

fn artifacts() -> Vec<&'static dyn GeneratedArtifact> {
    let mut list: Vec<&'static dyn GeneratedArtifact> = codegen::artifacts().to_vec();
    list.push(&ConformanceDocs);
    list.push(&BackendCaps);
    list.push(&GpuiCaps);
    list.push(&CONFORMANCE_XILEM_DOCS);
    list.push(&CONFORMANCE_FLOEM_DOCS);
    list.push(&CONFORMANCE_ICED_DOCS);
    list.push(&CONFORMANCE_EGUI_DOCS);
    list.push(&CONFORMANCE_SLINT_DOCS);
    list
}

/// Run the driver: arguments (WITHOUT the argv-0 program name), two
/// sinks, and the process exit code back — the aeolus-cli contract.
pub fn run<I>(args: I, out: &mut dyn std::io::Write, err: &mut dyn std::io::Write) -> i32
where
    I: IntoIterator<Item = String>,
{
    let argv: Vec<String> = args.into_iter().collect();
    if argv.iter().any(|a| a == "--help" || a == "-h") {
        let _ = write!(out, "{USAGE}");
        return EXIT_OK;
    }
    let Some(cmd) = argv.first() else {
        let _ = write!(err, "{USAGE}");
        return EXIT_USAGE;
    };
    let rest = &argv[1..];

    // The shared flag parse: `--check` (gen-tables only) and `--root`.
    let mut check = false;
    let mut root: Option<String> = None;
    let mut i = 0usize;
    while i < rest.len() {
        match rest[i].as_str() {
            "--check" if cmd != "list" => check = true,
            "--root" if i + 1 < rest.len() => {
                root = Some(rest[i + 1].clone());
                i += 1;
            }
            other => {
                let _ = writeln!(err, "unexpected argument {other:?}\n{USAGE}");
                return EXIT_USAGE;
            }
        }
        i += 1;
    }
    let root = root.map_or_else(default_root, PathBuf::from);

    match cmd.as_str() {
        "list" => {
            for artifact in artifacts() {
                let _ = writeln!(out, "{}  {}", artifact.name(), artifact.path());
            }
            EXIT_OK
        }
        "gen-tables" => walk(&root, check, out),
        "verify-tables" => walk(&root, true, out),
        "gen-gpui-caps" => {
            let (exit, report) = walk_one(&root, check, &GpuiCaps);
            let _ = out.write_all(report.as_bytes());
            exit
        }
        "verify-gpui-caps" => {
            let (exit, report) = walk_one(&root, true, &GpuiCaps);
            let _ = out.write_all(report.as_bytes());
            exit
        }
        other => {
            let _ = writeln!(err, "unknown command {other:?}\n{USAGE}");
            EXIT_USAGE
        }
    }
}

/// Walk the artifact seam in the requested mode: verify (compare
/// against the committed bytes) or write (replace them). Any drift or
/// missing file fails verify mode with the drift exit code — the gate
/// the pre-commit story runs.
fn walk(root: &Path, check: bool, out: &mut dyn std::io::Write) -> i32 {
    let mut exit = EXIT_OK;
    let mut report = String::new();
    for artifact in artifacts() {
        let (artifact_exit, artifact_report) = walk_one(root, check, artifact);
        exit = exit.max(artifact_exit);
        report.push_str(&artifact_report);
    }
    let _ = out.write_all(report.as_bytes());
    exit
}

/// Walk ONE artifact in the requested mode — the focused gate the
/// dedicated commands run (the same write/verify contract as the full
/// [`walk`], scoped to a single committed file). The exit code rides
/// beside the artifact's report line (empty only on a prepare/write
/// failure, whose message is the report).
fn walk_one(root: &Path, check: bool, artifact: &'static dyn GeneratedArtifact) -> (i32, String) {
    let path = root.join(artifact.path());
    let generated = artifact.generate();
    let outcome = if check {
        match std::fs::read_to_string(&path) {
            Ok(committed) if committed == generated => Outcome::Clean,
            Ok(_) => Outcome::Drifted,
            Err(_) => Outcome::Missing,
        }
    } else {
        // The parent directory's own failure is the report — the write
        // error would name the missing directory only indirectly, the
        // reason's context rides here (the no-silent-failures rule).
        if let Some(parent) = path.parent()
            && let Err(mk_err) = std::fs::create_dir_all(parent)
        {
            return (
                EXIT_DRIFT,
                format!(
                    "{}  {}  prepare failed: {mk_err}\n",
                    artifact.name(),
                    artifact.path()
                ),
            );
        }
        match std::fs::write(&path, &generated) {
            Ok(()) => Outcome::Wrote(generated.len()),
            Err(io_err) => {
                return (
                    EXIT_DRIFT,
                    format!(
                        "{}  {}  write failed: {io_err}\n",
                        artifact.name(),
                        artifact.path()
                    ),
                );
            }
        }
    };
    let report = outcome.report(artifact.name(), artifact.path());
    let exit = if matches!(outcome, Outcome::Clean | Outcome::Wrote(_)) {
        EXIT_OK
    } else {
        EXIT_DRIFT
    };
    (exit, report)
}
